#define MAX_HW 1000

int h, w;
char grid[MAX_HW][MAX_HW + 1];
int dist[MAX_HW][MAX_HW];

int dx[] = {1, -1, 0, 0};
int dy[] = {0, 0, 1, -1};

typedef struct {
    int x, y;
} Point;

Point queue[MAX_HW * MAX_HW];
int front, rear;

void enqueue(int x, int y) {
    queue[rear].x = x;
    queue[rear].y = y;
    rear++;
}

Point dequeue() {
    return queue[front++];
}

int is_empty() {
    return front == rear;
}

int main() {
    scanf("%d %d", &h, &w);
    for (int i = 0; i < h; i++) {
        scanf("%s", grid[i]);
    }

    // Initialize distances and enqueue all initial black squares
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            if (grid[i][j] == '#') {
                dist[i][j] = 0;
                enqueue(i, j);
            } else {
                dist[i][j] = -1;
            }
        }
    }

    int max_dist = 0;

    while (!is_empty()) {
        Point p = dequeue();
        int x = p.x;
        int y = p.y;
        for (int d = 0; d < 4; d++) {
            int nx = x + dx[d];
            int ny = y + dy[d];
            if (nx >= 0 && nx < h && ny >= 0 && ny < w && dist[nx][ny] == -1) {
                dist[nx][ny] = dist[x][y] + 1;
                if (dist[nx][ny] > max_dist) {
                    max_dist = dist[nx][ny];
                }
                enqueue(nx, ny);
            }
        }
    }

    printf("%d\n", max_dist);
    return 0;
}

