typedef struct {
    int r, c;
} Node;

int main(void) {
    int H, W;
    if (scanf("%d %d", &H, &W) != 2) return 0;

    char **grid = (char **)malloc(H * sizeof(char *));
    for (int i = 0; i < H; i++) {
        grid[i] = (char *)malloc((W + 1) * sizeof(char));
        scanf("%s", grid[i]);
    }

    int **dist = (int **)malloc(H * sizeof(int *));
    for (int i = 0; i < H; i++) {
        dist[i] = (int *)malloc(W * sizeof(int));
        for (int j = 0; j < W; j++) dist[i][j] = -1;
    }

    Node *queue = (Node *)malloc((size_t)H * W * sizeof(Node));
    int head = 0, tail = 0;

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (grid[i][j] == '#') {
                dist[i][j] = 0;
                queue[tail++] = (Node){i, j};
            }
        }
    }

    int dr[4] = {1, -1, 0, 0};
    int dc[4] = {0, 0, 1, -1};
    int ans = 0;

    while (head < tail) {
        Node cur = queue[head++];
        int r = cur.r, c = cur.c;

        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k];
            int nc = c + dc[k];
            if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;
            if (dist[nr][nc] != -1) continue;

            dist[nr][nc] = dist[r][c] + 1;
            if (dist[nr][nc] > ans) ans = dist[nr][nc];
            queue[tail++] = (Node){nr, nc};
        }
    }

    printf("%d\n", ans);

    for (int i = 0; i < H; i++) {
        free(grid[i]);
        free(dist[i]);
    }
    free(grid);
    free(dist);
    free(queue);

    return 0;
}

