def solve():
    H, W = map(int, input().split())
    grid = []
    for _ in range(H):
        grid.append(input().strip())

    dist = [[-1]*W for _ in range(H)]
    q = deque()

    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                dist[i][j] = 0
                q.append((i, j))

    ans = 0
    dirs = [(0,1),(0,-1),(1,0),(-1,0)]

    while q:
        r, c = q.popleft()
        for dr, dc in dirs:
            nr, nc = r+dr, c+dc
            if 0 <= nr < H and 0 <= nc < W and dist[nr][nc] == -1:
                dist[nr][nc] = dist[r][c] + 1
                ans = max(ans, dist[nr][nc])
                q.append((nr, nc))

    print(ans)

